<?php
$root=dirname(__DIR__); $build=$root.'/build'; $target=$build.'/simplyconnectsms'; $zip=$build.'/simplyconnectsms.zip';
if(is_dir($target)){ $it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($target,FilesystemIterator::SKIP_DOTS),RecursiveIteratorIterator::CHILD_FIRST); foreach($it as $item){$item->isDir()?rmdir($item->getPathname()):unlink($item->getPathname());} rmdir($target); } @mkdir($target,0777,true);
$included=['simplyconnectsms.php','config.xml','index.php','README.md','LICENSE','controllers','src','views'];
foreach($included as $relative){$source=$root.'/'.$relative;if(is_dir($source)){@mkdir($target.'/'.$relative,0777,true);$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($source,FilesystemIterator::SKIP_DOTS),RecursiveIteratorIterator::SELF_FIRST);foreach($it as $item){$dest=$target.'/'.$relative.'/'.$it->getSubPathName();$item->isDir()?@mkdir($dest,0777,true):copy($item->getPathname(),$dest);}}elseif(is_file($source)){@mkdir(dirname($target.'/'.$relative),0777,true);copy($source,$target.'/'.$relative);}}
file_put_contents($target.'/autoload.php',"<?php\n\ndefined('_PS_VERSION_') || exit;\n\nspl_autoload_register(static function (string \$class): void {\n    \$prefix = 'SimplyConnect\\\\PrestaShop\\\\';\n    if (str_starts_with(\$class, \$prefix)) {\n        \$path = __DIR__ . '/src/' . str_replace('\\\\', '/', substr(\$class, strlen(\$prefix))) . '.php';\n        if (is_readable(\$path)) { require_once \$path; }\n    }\n});\n");
@unlink($zip);$archive=new ZipArchive();$archive->open($zip,ZipArchive::CREATE);$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($target,FilesystemIterator::SKIP_DOTS));foreach($it as $item){if($item->isFile()){$archive->addFile($item->getPathname(),'simplyconnectsms/'.substr($item->getPathname(),strlen($target)+1));}}$archive->close();echo $zip.PHP_EOL;
